changeSet.sql:
-- Ajout de commande_client_id dans documents_comptables
ALTER TABLE IF EXISTS documents_comptables 
    ADD COLUMN IF NOT EXISTS commande_client_id BIGINT;

-- Ajout de livraison_id (BL Fournisseur) dans documents_comptables
ALTER TABLE IF EXISTS documents_comptables 
    ADD COLUMN IF NOT EXISTS livraison_id BIGINT;

-- Index pour les recherches instantanées des pièces jointes
CREATE INDEX IF NOT EXISTS idx_documents_comptables_cmd_client ON documents_comptables(commande_client_id);
CREATE INDEX IF NOT EXISTS idx_documents_comptables_livraison ON documents_comptables(livraison_id);
